#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn original_material_defaults_are_not_tuned_for_speed() {
        let s = Settings::default();
        assert_eq!(
            [
                s.resolution,
                s.sandResolution,
                s.lavaResolution,
                s.slimeResolution
            ],
            [6, 12, 6, 4]
        );
        assert_eq!(s.gravity, 9.81);
        assert_eq!(
            [s.flipRatio, s.lavaFlipRatio, s.slimeFlipRatio],
            [0.99, 0.9993, 0.9]
        );
        assert!(s.whitewater && s.wallFill && !s.sheetFill && !s.bucketMakesSource);
        assert!(s.tntReactions && s.lavaIgniteFlammables);
        assert_eq!(s.ffmpeg, "");
    }
}
